import assert from "node:assert/strict";
import { existsSync, readdirSync, readFileSync, statSync } from "node:fs";
import { join } from "node:path";
import { test } from "node:test";
import { fileURLToPath } from "node:url";
import { measureBudgets, pageAssets } from "../scripts/budgets.mjs";
import strawBoss, { createStrawBoss } from "../src/index.ts";

const root = fileURLToPath(new URL("..", import.meta.url));

// Pi reloads extension TypeScript on /reload, but Node caches native .js/.mjs modules for the
// life of the process. A relative JavaScript import would keep an old version after an upgrade.
test("extension code imports relative modules only as .ts", () => {
	for (const dir of ["src", "src/trust", "src/lan"]) {
		for (const name of readdirSync(join(root, dir)).filter((file) => file.endsWith(".ts"))) {
			for (const [, specifier] of readFileSync(join(root, dir, name), "utf8").matchAll(/from\s+["'](\.[^"']*)["']/g)) {
				// The one plain-JavaScript module the extension loads: exe.mjs finds programs by absolute path, and balance.mjs, which Node runs from node_modules where it will not strip types, needs it too.
				if (/(^|\/)exe\.mjs$/.test(specifier ?? "")) continue;
				assert.match(specifier ?? "", /\.ts$/, `${dir}/${name} imports ${specifier}`);
			}
		}
	}
});

test("the Asks' imports each stand on a line of their own, so the line budgets count them (asks-r2-F008)", () => {
	for (const [file, from] of [["src/boss.ts", "./askrows.ts"], ["gui/session.ts", "./asklist.ts"], ["gui/workspace.ts", "./asklist.ts"], ["src/index.ts", "./askrows.ts"]] as const) {
		const lines = readFileSync(join(root, file), "utf8").split("\n").filter((l) => l.includes(`"${from}"`));
		assert.ok(lines.length === 1 && /^import [^;]*;$/.test(lines[0]!), `${file}: the import of ${from} on a line of its own`);
	}
});

test("the module loads, its factory runs, and outside Herdr it registers nothing", () => {
	assert.equal(typeof strawBoss, "function");
	const registered: string[] = [];
	const pi = { on: (type: string) => registered.push(type), registerTool: () => registered.push("tool"), registerCommand: () => registered.push("command") };
	createStrawBoss({ env: {} })(pi as never);
	assert.deepEqual(registered, []);
});

test("the manifest ships only src, the built GUI and server bundles, prompts, the role pack (roles/), the subagent host's skill (skills/), README, NOTICE (the QR encoder's and pi-herdr-agents' MIT notices), the Maestro host's config example, and LICENSE, has tsx and the Maestro engine as its runtime dependencies, builds the bundles before packing and the page before testing, and points at a real entry", () => {
	const manifest = JSON.parse(readFileSync(join(root, "package.json"), "utf8"));
	assert.deepEqual(manifest.files, ["src", "dist/gui", "dist/server", "prompts", "roles", "skills", "README.md", "NOTICE.md", "config.json.example", "LICENSE"]);
	assert.deepEqual(manifest.pi.skills, ["./skills"], "the subagent host's operating skill");
	// tsx: the server loads pi-intercom's TypeScript client through it (docs/specs/2026-10-26-sb-backend.md, Process model). @nubl/maestro: the subagent engine src/host/ hosts, a git dependency with committed dist/ (spike 0a).
	assert.deepEqual(Object.keys(manifest.dependencies).sort(), ["@nubl/maestro", "tsx"]);
	assert.match(manifest.dependencies["@nubl/maestro"], /^git\+https:\/\/github\.com\/wayne930242\/maestro\.git#[0-9a-f]{40}$/, "Maestro is pinned to a full commit over https");
	assert.ok(manifest.devDependencies.vite, "the page is built with Vite, as a development dependency only");
	assert.equal(manifest.scripts.prepack, "npm run gui:build && npm run build:server");
	assert.equal(manifest.scripts.pretest, "npm run gui:build");
	assert.ok(manifest.keywords.includes("pi-package"));
	assert.equal(manifest.peerDependencies["@earendil-works/pi-coding-agent"], "*");
	assert.equal(manifest.peerDependencies["@earendil-works/pi-tui"], "*");
	for (const entry of manifest.pi.extensions) assert.ok(existsSync(join(root, entry)), entry);
});

// The block chunk bundles code under licenses that ask for their notice to go with copies (the npm package ships dist/gui): pi-better-show (MIT) and yaml (ISC).
test("NOTICE.md carries the notices of what the block chunk bundles, with the version and licence text of each", () => {
	const notice = readFileSync(join(root, "NOTICE.md"), "utf8");
	const manifest = JSON.parse(readFileSync(join(root, "package.json"), "utf8")) as { devDependencies: Record<string, string> };
	const shipped = (name: string) => JSON.parse(readFileSync(join(root, "node_modules", name, "package.json"), "utf8")) as { version: string };
	const chunk = readdirSync(join(root, "dist/gui/assets")).find((name) => /^blockschunk-.*\.js$/.test(name));
	assert.ok(chunk, "the build has a block chunk");
	assert.match(notice, /## pi-better-show/);
	assert.ok(notice.includes(`pi-better-show](https://github.com/wayne930242/pi-better-show) ${manifest.devDependencies["pi-better-show"]}`), "the pinned version");
	assert.match(notice, /MIT License, Copyright \(c\) 2026 wayne930242/);
	assert.match(notice, /yaml\]\(https:\/\/github\.com\/eemeli\/yaml\) library \d+\.\d+\.\d+/);
	assert.match(notice, /ISC License, Copyright Eemeli Aro/);
	assert.match(notice, /Permission to use, copy, modify, and\/or distribute this software for any purpose/);
	const yaml = JSON.parse(readFileSync(join(root, "node_modules/pi-better-show/node_modules/yaml/package.json"), "utf8")) as { version: string };
	assert.ok(notice.includes(`library ${yaml.version}`), "the bundled yaml's version (the package's own copy)");
	void shipped;
});

