test("the built page is small, self-contained (no remote URLs, fonts, or imports), and carries no demo fixture", { skip: !existsSync(join(root, "dist/gui/index.html")) && "run npm run gui:build first" }, () => {
	const dir = join(root, "dist/gui");
	const files = [join(dir, "index.html"), ...readdirSync(join(dir, "assets")).filter((name) => !name.endsWith(".woff2")).map((name) => join(dir, "assets", name))];
	// The one font: the Nerd Font symbols a pane's screen may show (about 1.1 MB), served by the page's own server and fetched only for such a glyph.
	const fonts = readdirSync(join(dir, "assets")).filter((name) => name.endsWith(".woff2"));
	assert.ok(fonts.length === 1 && fonts[0]!.startsWith("SymbolsNerdFontMono-") && statSync(join(dir, "assets", fonts[0]!)).size <= 1_200_000, `fonts: ${fonts.join(", ")}`);
	const text = files.map((file) => readFileSync(file, "utf8")).join("\n");
	// Paraglide's runtime names two placeholder origins in its URL helpers and its docs in an error message; the page fetches none of them.
	const named = ["http://www.w3.org/2000/svg", "http://example.com", "http://fallback.com", "https://paraglidejs.com/errors#no-locale-found"];
	const remote = [...text.matchAll(/https?:\/\/[^\s"'`)]+/g)].map((m) => m[0]).filter((url) => !named.includes(url));
	assert.deepEqual(remote, [], "nothing is fetched from elsewhere");
	assert.ok(!/@import|<link[^>]+href="https?:/.test(text));
	assert.ok(!text.includes("Harbor API") && !text.includes("demo fixture") && !text.includes("harbor-1"), "the demo fixture stays out of the bundle");
	assert.ok(/EventSource/.test(text), "the built page reads the live stream");
	assert.ok(!/\.innerHTML\s*=|insertAdjacentHTML/.test(text), "no page code writes markup");
	const assets = readdirSync(join(dir, "assets")), size = (name: string) => readFileSync(join(dir, "assets", name));
	const { eager } = pageAssets(dir);
	assert.ok([...eager].some((name) => name.startsWith("boot-")), "boot.js is among the files loaded at start");
	// pi-better-show's elements load lazily (todo #129): only the block chunk (blockschunk-*) holds them, and only mdbody's dynamic import reaches it; no eager file, and no chunk of the chat, the documents, or Zen, carries a block element or the package's parser.
	const withBlocks = assets.filter((name) => name.endsWith(".js") && /pbs-callout|pbs-answer/.test(size(name).toString()));
	assert.equal(withBlocks.length, 1, `the block elements are in one chunk: ${withBlocks.join(", ")}`);
	assert.match(withBlocks[0]!, /^blockschunk-/);
	assert.ok(!eager.has(withBlocks[0]!), "the block chunk is not loaded at start");
	assert.ok(![...eager].some((name) => name.endsWith(".js") && /blockschunk/.test(size(name).toString())), "no eager file names the block chunk: it is a dynamic import");
	assert.ok(assets.some((name) => /^blockschunk-.*\.css$/.test(name)), "the token map is the block chunk's own stylesheet");
	const musicChunk = readdirSync(join(dir, "themes", "zen")).find((n) => n.startsWith("zenmusic-")); // zenmusic.ts is a chunk of its own, in the Zen theme's folder: at most 4 KB raw (the spec's Asset budget)
	assert.ok(musicChunk, "the music chunk (createPlayer) is in the build");
	const musicSize = readFileSync(join(dir, "themes", "zen", musicChunk)).length;
	assert.ok(musicSize <= 4096, `the music chunk is ${musicSize} bytes`);
});

// The Zen rows of the keymap exist only because the Zen theme's entry imports zenrows.ts for its side effect: nothing else loads them in the page, so dropping that "unused" import leaves Enter, H, [, ], and the palette key dead while every other test stays green.
test("the Zen theme's entry imports zenrows.ts, which registers the Zen keymap rows", () => {
	assert.match(readFileSync(join(root, "gui/themes/zen/index.ts"), "utf8"), /^import\s+["']\.\.\/\.\.\/zenrows\.ts["'];?/m);
	assert.match(readFileSync(join(root, "gui/zenrows.ts"), "utf8"), /KEYMAP\.zen\s*=|KEYMAP\[["']zen["']\]\s*=/);
});

test("the built themes and page stay within their byte budgets", () => {
	const figures = measureBudgets(join(root, "dist/gui"));
	const budgets = JSON.parse(readFileSync(join(root, "tests/budgets.json"), "utf8"));
	assert.deepEqual(Object.keys(figures).sort(), Object.keys(budgets).sort(), "one budget for every theme and page group");
	for (const [name, actual] of Object.entries(figures)) {
		const row = budgets[name];
		assert.ok(actual.raw <= row.ceiling, `${name}: ${actual.raw} raw bytes exceed ceiling ${row.ceiling}`);
		for (const unit of ["raw", "gz"] as const) {
			const limit = Math.floor(row[unit] + Math.max(row[unit] / 100, 2048));
			assert.ok(actual[unit] <= limit, `${name}: ${actual[unit]} ${unit} bytes exceed ${limit} (recorded ${row[unit]})`);
		}
	}
});

test("Zen's own modules do not import the trains model statically: a computer with no trains carries none of its words (TPG-F001, spec §26)", () => {
	for (const name of readdirSync(join(root, "gui")).filter((n) => /^zen.*\.ts$/.test(n))) assert.doesNotMatch(readFileSync(join(root, "gui", name), "utf8"), /^import\s[^;]*from\s+["']\.\/trains\.ts["']/m, `gui/${name} imports trains.ts at start`);
	assert.match(readFileSync(join(root, "gui/zenpage.ts"), "utf8"), /import\(["']\.\/trains\.ts["']\)/, "zenpage loads it once a snapshot carries yards");
});

test("headless runs type into no pane (docs/specs/2026-11-23-lite-b2-d-e-f.md §4.8 test 5, as far as the switch release allows): only standing.ts types (`pane run`), and the headless modules import nothing of Herdr", () => {
	const server = readdirSync(join(root, "src/server")).filter((n) => n.endsWith(".ts"));
	const typers = server.filter((n) => /\["pane", "run"/.test(readFileSync(join(root, "src/server", n), "utf8")));
	assert.deepEqual(typers, ["standing.ts"]);
	for (const file of ["src/server/runchild.ts", "src/server/runkids.ts", "src/server/runring.ts", "src/server/entrycmds.ts", "src/towerprompt/entry.ts"]) {
		const text = readFileSync(join(root, file), "utf8");
		assert.doesNotMatch(text, /startPi|"agent", "start"|send-keys|send-text/, `${file} starts or types into no pane`);
	}
	// The pane path (runs.ts `launch` with herdr.ts `startPi`) stays behind `towerRuns.headless` off for this release; the release that deletes it makes this test the full §4.8 rule.
	assert.match(readFileSync(join(root, "src/server/runs.ts"), "utf8"), /if \(active\.headless \|\| headlessOn\(\)\) return launchKid\(/);
});
